import sys,json,shutil
import numpy as np
from scipy import sparse
from scipy.linalg import lstsq
from baseline_registry import ROOT,REPO,ref,sha,dump
from primary_ritz_storage import load as load_ritz

def main():
 out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated/primaryP1_extended_continuation1/summary.json';s=json.loads(src.read_text());old=json.loads((REPO/s['source']['path']).read_text());d=np.load(REPO/s['reduced']['path']);a=np.load(REPO/s['output']['path']);parent=json.loads((REPO/old['source']['path']).read_text());r=load_ritz(json.loads((REPO/parent['source']['path']).read_text()));part=json.loads((REPO/old['partition_source']['path']).read_text());partdata=np.load(REPO/part['output']['path']);v=partdata['physical_probe'];V=np.column_stack([r['V'],v]);P=sparse.load_npz(REPO/old['physical_P']['path']);A=sparse.load_npz(REPO/old['physical_A']['path']);p=np.load(REPO/old['problem']['path']);x=r['before_x'];B=A@V;H=V.T@(P@V);g=V.T@(P@x+p['q']);eq=np.isfinite(p['upper'])&(p['lower']==p['upper']);ine=~eq;N,cp,unit=d['N'],d['cp'],float(d['unit']);rs=1/np.maximum(np.max(abs(B),axis=1),1e-15);HH=N.T@H@N/unit;gg=N.T@(g+H@cp)/unit;F=(rs[ine,None]*B[ine])@N;b=rs[ine]*((A@x-p['lower'])[ine]+B[ine]@cp)
 z=a['z'];coeff=cp+N@z;proposal=x+V@coeff;y=a['physical_dual'];sl=A@proposal-p['lower'];res=P@proposal+p['q']+A.T@y
 metrics=dict(primal_mm=max(float(np.max(np.maximum(-sl[ine],0))),float(np.max(abs(sl[eq])))),stationarity_N=float(np.max(abs(res))),gauge_N=float(np.max(abs(y[eq]))),RootY_gamma_stationarity_N=float(abs(y[2175])),sign_N=float(np.max(np.maximum(y[ine],0))),complementarity_Nmm=float(np.max(abs(sl[ine]*y[ine]))),reduced_stationarity=float(np.max(abs(V.T@res))))
 D=partdata['D'];Z=V/D[:,None];scaled=np.asarray(D*res,dtype=float);parallel=Z@lstsq(Z,scaled,cond=1e-14)[0];perp=scaled-parallel;probe=-D*perp/np.linalg.norm(perp);work=float(-res@probe);curvature=float(probe@(P@probe));orth=float(np.max(abs(Z.T@(probe/D))))
 np.savez_compressed(out/'missing_mode.npz',physical_probe=probe,physical_residual=res,D=D,scaled_residual=scaled,orthogonal_residual=perp)
 expected_y=np.zeros(A.shape[0],dtype=np.longdouble);expected_y[ine]=-unit*rs[ine]*a['l'];expected_y[eq]=lstsq(B[eq].T,np.asarray(-(H@coeff+g+B[ine].T@expected_y[ine]),dtype=float),cond=1e-14)[0]
 checks=dict(all2208rows=A.shape[0]==2208,all131columns=V.shape[1]==131,original_reduced_H=np.max(abs(HH-d['H']))<1e-7,original_F=np.max(abs(F-d['F']))<1e-10,original_b=np.max(abs(b-d['b']))<1e-10,endpoint=np.max(abs(proposal-a['proposed_x']))<1e-12,force=np.max(abs(res-a['physical_residual']))<1e-8,physical_dual=np.max(abs(expected_y-y))<1e-8,metrics=all(abs(metrics[k]-s['metrics'][k])<1e-10 for k in metrics),orthogonal_mode=orth<1e-8,positive_curvature=curvature>0,work_identity=abs(work-np.linalg.norm(perp))<1e-10,physical_rejection=not s['physical_KKT_qualified'] and metrics['stationarity_N']>1e-8 and metrics['primal_mm']>1e-10)
 cad=json.loads((REPO/s['candidate']['path']).read_text());checks['actual78STEP']=len(cad['part_references'])==78 and all(sha(REPO/v['path'])==v['SHA256'] for v in cad['part_references'].values());checks['source_hashes']=all(sha(REPO/s[k]['path'])==s[k]['SHA256'] for k in ['candidate','source','source_field','reduced','output'])
 controls=dict(reversed_work=-work,omitted_contact_force=float(np.max(abs((P@proposal+p['q'])-res))),wrong_scaling_norm=float(np.linalg.norm(np.asarray(res,dtype=float))))
 checks['negative_controls']=controls['reversed_work']<0 and controls['omitted_contact_force']>1e-8 and abs(controls['wrong_scaling_norm']-np.linalg.norm(scaled))>1e-8
 ok=all(checks.values());dump(out/'summary.json',dict(status='ACTUAL_P1_ENDPOINT_AUDIT_PASS' if ok else 'ACTUAL_P1_ENDPOINT_AUDIT_FAIL',candidate=s['candidate'],source=ref(src),verifier=ref(out/'verifier.py'),output=ref(out/'missing_mode.npz'),checks={k:bool(v) for k,v in checks.items()},metrics=metrics,partition=dict(scaled_residual_norm=float(np.linalg.norm(scaled)),parallel_norm=float(np.linalg.norm(parallel)),orthogonal_norm=float(np.linalg.norm(perp)),orthogonal_fraction=float(np.linalg.norm(perp)/np.linalg.norm(scaled)),all131_orthogonality=orth,work_Nmm=work,curvature_Nmm=curvature,maximum_original_row_motion_mm=float(np.max(abs(A@probe)))),negative_controls=controls,physical_KKT_qualified=False,actual_support_updates=0,accepted_equilibria=0,newly_qualified_system_gate_ids=[],whole_system_release=False));print(json.dumps(dict(checks=checks,metrics=metrics),default=bool));raise SystemExit(0 if ok else 2)
if __name__=='__main__':main()
